    uint32_t i,matched;float input[8];rf_geomod_debris_liquid_hit value,before;
    memset(&before,0xa5,sizeof(before));
    for(i=0;i<sizeof(cases)/sizeof(cases[0]);i++) {
        memcpy(input,cases[i].input,sizeof(input));value=before;matched=99;
        CHECK(rf_geomod_debris_liquid_miss(input,input+3,cases[i].flag,input[6],input[7],&value,&matched)==RF_OK);
        CHECK(matched==cases[i].matched);
        CHECK(!memcmp(&value,matched?(const void*)cases[i].result:(const void*)&before,sizeof(value)));
    }
    input[0]=1;input[1]=2;input[2]=3;input[3]=5;input[4]=-2;input[5]=9;
    value=before;matched=99;
    CHECK(rf_geomod_debris_liquid_miss(input,input+3,1,INFINITY,0,&value,&matched)==RF_RANGE);
    CHECK(matched==99 && !memcmp(&value,&before,sizeof(value)));
    CHECK(rf_geomod_debris_liquid_miss(input,input+3,1,2147483648.0f,0,&value,&matched)==RF_RANGE);
    CHECK(matched==99 && !memcmp(&value,&before,sizeof(value)));
    CHECK(rf_geomod_debris_liquid_miss(input,input+3,256,NAN,NAN,&value,&matched)==RF_OK);
    CHECK(matched==0 && !memcmp(&value,&before,sizeof(value)));
    puts("PASS 225 original wet-miss vectors, raw-height boundary and transactional guards");return 0;
